namespace sv_ad8d862991304b20893addf676599455.Services;

public enum Theme { Light, Dark, System }

public sealed class ThemeService : IDisposable
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// All interactive components subscribing to this event will re-render.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();

    public void Dispose() => OnChange = null;
}

@* Interactive island embedded in the static MainLayout.
   Shares the same scoped ThemeService as every other interactive component in the circuit. *@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" title="Current theme">
    @switch (ThemeService.Theme)
    {
        case Theme.Light:
            <span>☀️ Light</span>
            break;
        case Theme.Dark:
            <span>🌙 Dark</span>
            break;
        case Theme.System:
            <span>💻 System</span>
            break;
    }
    <span class="accent-dot" style="background-color: @ThemeService.AccentColor;"></span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@* Reusable toggle — drop into any interactive page or component. *@
@inject ThemeService ThemeService
@implements IDisposable

<div class="theme-toggle">
    <span>Theme:</span>
    @foreach (var t in Enum.GetValues<Theme>())
    {
        <button class="btn btn-sm @(ThemeService.Theme == t ? "btn-primary" : "btn-outline-secondary")"
                @onclick="() => ThemeService.Theme = t">
            @t
        </button>
    }
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChanged;
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div>
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <button class="btn @(ThemeService.Theme == t ? "btn-primary" : "btn-outline-secondary") me-2"
                    @onclick="() => ThemeService.Theme = t">
                @t
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accent">Accent Color</label>
    <input id="accent" type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="OnAccentChanged" />
</div>

<p class="mt-4">
    Current: <strong>@ThemeService.Theme</strong> &mdash;
    Accent: <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChanged;
    }
}

